#!/bin/sh
# Runs once, on first start of an empty data volume. One database + one owner
# role per service so a bug in one service can't touch another's data.
# Passwords come from postgres.env (generated by scripts/bootstrap.sh).
set -eu

create() {
  db="$1"; role="$2"; pass="$3"
  psql -v ON_ERROR_STOP=1 -U postgres <<SQL
CREATE ROLE ${role} LOGIN PASSWORD '${pass}';
CREATE DATABASE ${db} OWNER ${role};
REVOKE ALL ON DATABASE ${db} FROM PUBLIC;
SQL
}

create qura_client qura_client "${QURA_CLIENT_DB_PASSWORD}"
create qura_crm qura_crm "${QURA_CRM_DB_PASSWORD}"
